   entries.Add("Turn this on to lift the restriction: every value 1–39 becomes settable and the axis is drawn straight. Nothing about the EC write changes — those values were always sent as-is. Switching it back off snaps the curve onto the allowed values again.",new[]{"Turn this on to lift the restriction: every value 1–39 becomes settable and the axis is drawn straight. Nothing about the EC write changes — those values were always sent as-is. Switching it back off snaps the curve onto the allowed values again.","Разрешает любые значения 1–39% и убирает разрыв оси. Способ записи EC не меняется. При отключении значения кривой возвращаются к допустимому диапазону."});
  }
  static void Add7(Dictionary<string,string[]> entries)
  {
   entries.Add("Per-game gyro engine",new[]{"Per-game gyro engine","Обработка гироскопа игрового профиля"});
   entries.Add("Which engine a per-game controller profile's gyro uses. Auto reads the sensor over the COM Sensor API — the one path that works on the Claw 8 AI+ and the Claw 8 EX alike, confirmed on real hardware on both. If the Sensor API finds nothing, Auto falls back to the WinRT sensor by itself. Applies immediately.",new[]{"Which engine a per-game controller profile's gyro uses. Auto reads the sensor over the COM Sensor API — the one path that works on the Claw 8 AI+ and the Claw 8 EX alike, confirmed on real hardware on both. If the Sensor API finds nothing, Auto falls back to the WinRT sensor by itself. Applies immediately.","Автоматический режим читает датчики через COM Sensor API. Этот путь проверен на Claw 8 AI+ и Claw 8 EX. Если датчик не найден, используется WinRT. Изменение применяется сразу."});
   entries.Add("The other entries are for testing: 'Virtual (software)' forces the WinRT sensor (which finds nothing on the EX, whose gyro reports a different type ID), 'Firmware (SensorModule)' leaves motion to the controller itself, and 'Virtual (Sensor API)' pins the COM source with no fallback.",new[]{"The other entries are for testing: 'Virtual (software)' forces the WinRT sensor (which finds nothing on the EX, whose gyro reports a different type ID), 'Firmware (SensorModule)' leaves motion to the controller itself, and 'Virtual (Sensor API)' pins the COM source with no fallback.","Остальные режимы предназначены для проверки: виртуальный программный принудительно использует WinRT; аппаратный SensorModule передаёт движение прошивке; виртуальный Sensor API использует только COM без запасного источника."});
