  static void Add19(Dictionary<string,string[]> entries)
  {
   entries.Add("Virtual controller type",new[]{"Virtual controller type","Тип виртуального контроллера"});
   entries.Add("Saved in this controller profile. Changing type briefly reconnects the virtual controller. Xbox 360 offers the widest game compatibility. Keyboard & mouse temporarily uses Xbox 360; the saved choice is retained.",new[]{"Saved in this controller profile. Changing type briefly reconnects the virtual controller. Xbox 360 offers the widest game compatibility. Keyboard & mouse temporarily uses Xbox 360; the saved choice is retained.","Сохраняется в этом профиле. Смена типа кратко переподключает виртуальный контроллер. Xbox 360 наиболее совместим с играми. Режим клавиатуры и мыши временно использует Xbox 360, сохраняя выбор профиля."});
   entries.Add("Forward motion to DS4 games",new[]{"Forward motion to DS4 games","Передавать движение в игры DS4"});
   entries.Add("Requires Virtual Controller + DualShock 4. Sends the sensor's rotation and acceleration axes to the game. Configure motion controls in the game or Steam Input. Separate from gyro-to-stick/mouse; forwarding pauses while ONEXTweaks is open.",new[]{"Requires Virtual Controller + DualShock 4. Sends the sensor's rotation and acceleration axes to the game. Configure motion controls in the game or Steam Input. Separate from gyro-to-stick/mouse; forwarding pauses while ONEXTweaks is open.","Требуется виртуальный контроллер DualShock 4. Передаёт вращение и ускорение датчиков игре. Управление движением настраивается в игре или Steam Input. Это отдельная функция от гироскопа как стика или мыши; при открытом ONEXTweaks передача приостанавливается."});
   entries.Add("Forward game lighting to LEDs",new[]{"Forward game lighting to LEDs","Передавать цвет игры на LED"});
   entries.Add("Requires DualShock 4 and the updated hardware helper. Temporarily uses game-requested colors while keeping your zone brightness and calibration. Saved LED colors stay unchanged. Editing LED settings stops the current game override; re-enable this option or select another profile to accept new game colors.",new[]{"Requires DualShock 4 and the updated hardware helper. Temporarily uses game-requested colors while keeping your zone brightness and calibration. Saved LED colors stay unchanged. Editing LED settings stops the current game override; re-enable this option or select another profile to accept new game colors.","Требуются DualShock 4 и обновлённый аппаратный помощник. Временно использует цвета игры с вашей яркостью зон и калибровкой. Сохранённые цвета не меняются. Изменение настроек LED останавливает подмену; включите опцию снова или выберите другой профиль для новых цветов игры."});
   entries.Add("Global и ручные профили используют тот же Choose / Create. Профиль, связанный с Performance, выбирается при его активации; ручной выбор действует до смены или перезапуска игрового контекста. После сна или отключения контроллера может потребоваться снова включить режим.",new[]{"Global and manual profiles use the same Choose / Create controls. A linked Performance profile selects this controller profile when activated. Manual selection lasts until the game context changes or restarts. After sleep or disconnecting the controller, you may need to enable the mode again.","Глобальные и ручные профили используют общий выбор и создание. Связанный профиль производительности выбирает этот профиль контроллера при активации. Ручной выбор действует до смены или перезапуска игрового контекста. После сна или отключения контроллера может потребоваться включить режим снова."});
   entries.Add("Physical control",new[]{"Physical control","Физический элемент"});
   entries.Add("Extra {0} (firmware)",new[]{"Extra {0} (firmware)","Доп. {0} (прошивка)"});
   entries.Add("Front · Home",new[]{"Front · Home","Спереди · Home"});
   entries.Add("Front · G-Key / Xbox",new[]{"Front · G-Key / Xbox","Спереди · G-Key / Xbox"});
   entries.Add("Front · Keyboard / mouse",new[]{"Front · Keyboard / mouse","Спереди · Клавиатура / мышь"});
   entries.Add("Front · ONEX",new[]{"Front · ONEX","Спереди · ONEX"});
   entries.Add("Rear · M1",new[]{"Rear · M1","Сзади · M1"});
   entries.Add("Rear · M2",new[]{"Rear · M2","Сзади · M2"});
   entries.Add("Virtual control",new[]{"Virtual control","Виртуальный элемент"});
   entries.Add("Xbox / Guide",new[]{"Xbox / Guide","Xbox / Guide"});
   entries.Add("Keyboard shortcut",new[]{"Keyboard shortcut","Сочетание клавиш"});
   entries.Add("Press keyboard keys · B / Esc cancels",new[]{"Press keyboard keys · B / Esc cancels","Нажмите клавиши · B / Esc — отмена"});
   entries.Add("Mouse action",new[]{"Mouse action","Действие мыши"});
   entries.Add("Deadzone убирает движение около центра: например, 5% помогает при небольшом дрейфе. Порог триггера используется только при назначении ему кнопки/клавиши; аналоговый диапазон задаётся отдельно для LT и RT выше. Порог назначения сравнивается с настроенным выходом триггера. Тач: 1%, геймпад: 5%.",new[]{"Deadzone removes movement near the centre: 5% can help with slight drift. The button threshold applies only when assigning a button or key to a trigger; the analogue range is set separately for LT and RT above. The threshold is compared with the configured trigger output. Touch: 1%; gamepad: 5%.","Мёртвая зона убирает движение около центра: 5% может помочь при небольшом дрейфе. Порог назначения действует только при назначении кнопки или клавиши на триггер. Аналоговый диапазон LT и RT задаётся выше; порог сравнивается с настроенным выходом. Тач: 1%, геймпад: 5%."});
