  static void Add20(Dictionary<string,string[]> entries)
  {
   entries.Add("Activate button",new[]{"Activate button","Кнопка активации"});
   entries.Add("Hold: aim while the physical button is held. Toggle: press once to arm, again to stop. None or Always keeps aiming available. Opening Game Bar or changing profiles clears Toggle; press again to re-arm. M1/M2 require Extra Buttons to be on.",new[]{"Hold: aim while the physical button is held. Toggle: press once to arm, again to stop. None or Always keeps aiming available. Opening Game Bar or changing profiles clears Toggle; press again to re-arm. M1/M2 require Extra Buttons to be on.","Удержание — наведение при удержании физической кнопки. Переключение — одно нажатие включает, второе выключает. Нет или Всегда оставляет наведение включённым. Game Bar и смена профиля сбрасывают переключение; нажмите снова. Для M1/M2 нужны включённые дополнительные кнопки."});
   entries.Add("Hold-boost changes sensitivity only while its button is held. Example: 50% gives slower aiming, 200% gives faster turns. Mouse and sticks use the same X/Y settings; the stick result is added to your normal stick input.",new[]{"Hold-boost changes sensitivity only while its button is held. Example: 50% gives slower aiming, 200% gives faster turns. Mouse and sticks use the same X/Y settings; the stick result is added to your normal stick input.","Усиление действует только при удержании его кнопки. 50% — медленнее, 200% — быстрее. Мышь и стики используют одни настройки X/Y; выход стика добавляется к физическому вводу."});
   entries.Add("Restore Gyro Defaults",new[]{"Restore Gyro Defaults","Сбросить гироскоп"});
   entries.Add("Current aiming: {0}",new[]{"Current aiming: {0}","Текущее наведение: {0}"});
   entries.Add("Settings save automatically in the selected controller profile.",new[]{"Settings save automatically in the selected controller profile.","Настройки автоматически сохраняются в выбранном профиле контроллера."});
   entries.Add("Choose Virtual Controller to use gyro aiming. Sensor calibration stays available in Hardware mode.",new[]{"Choose Virtual Controller to use gyro aiming. Sensor calibration stays available in Hardware mode.","Для наведения нужен виртуальный контроллер. Калибровка датчиков доступна и в аппаратном режиме."});
   entries.Add("Axes & orientation",new[]{"Axes & orientation","Оси и ориентация"});
   entries.Add("Gyro-to-stick horizontal input",new[]{"Gyro-to-stick horizontal input","Горизонтальная ось гироскопа → стик"});
   entries.Add("Output rotation",new[]{"Output rotation","Поворот выхода"});
   entries.Add("Gravity-relative aiming uses the accelerometer to find vertical. Example: turn left/right while holding the console upright or lying flat. Off uses the console's own axes. Aiming pauses if gravity data cannot be used.",new[]{"Gravity-relative aiming uses the accelerometer to find vertical. Example: turn left/right while holding the console upright or lying flat. Off uses the console's own axes. Aiming pauses if gravity data cannot be used.","Наведение относительно гравитации определяет вертикаль акселерометром. Можно поворачивать консоль влево/вправо как вертикально, так и лёжа. Выкл. использует оси самой консоли. Без пригодных данных гравитации наведение приостанавливается."});
   entries.Add("For stick targets, Yaw uses the console’s −Y rotation and Roll uses −Z. Yaw + Roll adds both. Example: choose Roll to aim horizontally by tilting like a steering wheel. Invert X reverses the direction. Pitch continues to use X.",new[]{"For stick targets, Yaw uses the console’s −Y rotation and Roll uses −Z. Yaw + Roll adds both. Example: choose Roll to aim horizontally by tilting like a steering wheel. Invert X reverses the direction. Pitch continues to use X.","Для стиков Yaw использует вращение −Y, Roll — −Z, Yaw + Roll складывает их. Roll позволяет наводить наклоном как руля. Инверсия X меняет направление. Pitch использует X."});
   entries.Add("Manual Yaw / Roll selection is inactive for Mouse and while Gravity-relative aiming is On; its saved choice returns when you switch back. Gravity-relative aiming already adapts to the console’s posture.",new[]{"Manual Yaw / Roll selection is inactive for Mouse and while Gravity-relative aiming is On; its saved choice returns when you switch back. Gravity-relative aiming already adapts to the console’s posture.","Ручной выбор Yaw / Roll недоступен для мыши и при наведении относительно гравитации. Сохранённый выбор возвращается при переключении обратно. Гравитационное наведение само учитывает положение консоли."});
   entries.Add("Invert X reverses left/right; Invert Y reverses up/down. Output rotation turns the aiming axes for a rotated grip. Example: 90° maps horizontal motion onto the vertical axis. Start with 0° for the normal grip.",new[]{"Invert X reverses left/right; Invert Y reverses up/down. Output rotation turns the aiming axes for a rotated grip. Example: 90° maps horizontal motion onto the vertical axis. Start with 0° for the normal grip.","Инверсия X меняет лево/право, Y — верх/низ. Поворот выхода разворачивает оси: 90° превращает горизонтальное движение в вертикальное. Для обычного хвата начните с 0°."});
   entries.Add("Stick response curve",new[]{"Stick response curve","Кривая отклика стика"});
   entries.Add("Use custom gyro-to-stick response",new[]{"Use custom gyro-to-stick response","Своя кривая гироскопа → стик"});
   entries.Add("For Left/Right Stick targets. Off keeps the previous response. On uses the curve below; Min stick output replaces the separate Anti-deadzone value while this curve is active.",new[]{"For Left/Right Stick targets. Off keeps the previous response. On uses the curve below; Min stick output replaces the separate Anti-deadzone value while this curve is active.","Для левого и правого стиков. Выкл. сохраняет прежний отклик. Вкл. использует кривую ниже; минимальный выход заменяет отдельную антимёртвую зону, пока кривая активна."});
   entries.Add("Restore Curve Defaults",new[]{"Restore Curve Defaults","Сбросить кривую"});
   entries.Add("Input speed is measured after axis settings, sensitivity and filtering. The larger of Deadzone / Min input speed is ignored. Example: 220°/s reaches Max output with sensitivity 1.00×. Raise sensitivity for quicker turns.",new[]{"Input speed is measured after axis settings, sensitivity and filtering. The larger of Deadzone / Min input speed is ignored. Example: 220°/s reaches Max output with sensitivity 1.00×. Raise sensitivity for quicker turns.","Скорость измеряется после настройки осей, чувствительности и фильтров. Движение ниже большего из мёртвой зоны и минимальной скорости игнорируется. При чувствительности 1,00× скорость 220°/s даёт максимальный выход. Повышайте чувствительность для быстрых поворотов."});
   entries.Add("Power 1.00× is linear; 2.00× makes small movements gentler; 0.50× makes them stronger. Precision range slows movements near the threshold. Example: 30°/s adds fine control during slow tilts.",new[]{"Power 1.00× is linear; 2.00× makes small movements gentler; 0.50× makes them stronger. Precision range slows movements near the threshold. Example: 30°/s adds fine control during slow tilts.","Степень 1,00× — линейно, 2,00× — мягче малые движения, 0,50× — резче. Диапазон точности замедляет движения у порога: например, 30°/s облегчает медленные наклоны."});
   entries.Add("Min output helps cross a game's stick deadzone; Max output caps the gyro contribution. Example: 20% / 70% stays between those radii while moving. Physical stick input is added afterwards. Output mix +50% halves vertical motion; −50% halves horizontal motion.",new[]{"Min output helps cross a game's stick deadzone; Max output caps the gyro contribution. Example: 20% / 70% stays between those radii while moving. Physical stick input is added afterwards. Output mix +50% halves vertical motion; −50% halves horizontal motion.","Минимальный выход преодолевает мёртвую зону игры; максимальный ограничивает вклад гироскопа. 20% / 70% держит радиус в этих пределах. Физический стик добавляется после. Смешивание +50% вдвое уменьшает вертикаль, −50% — горизонталь."});
   entries.Add("Motion processing",new[]{"Motion processing","Обработка движения"});
   entries.Add("Higher smoothing reduces small jitters but adds delay. Example: use a little smoothing for fast aiming, more for a shaky hand. Adaptive and Precision remember their own value. Touch: 1%; gamepad: 5%. Linear keeps previous profiles unchanged.",new[]{"Higher smoothing reduces small jitters but adds delay. Example: use a little smoothing for fast aiming, more for a shaky hand. Adaptive and Precision remember their own value. Touch: 1%; gamepad: 5%. Linear keeps previous profiles unchanged.","Сглаживание уменьшает дрожание, но добавляет задержку. Малое значение подходит для быстрых движений, большее — для дрожащих рук. Адаптивный и точный режимы запоминают отдельные значения. Тач: 1%, геймпад: 5%. Линейный сохраняет прежнее поведение."});
   entries.Add("Linear · direct response, no software smoothing. Example: a small tilt produces a proportional movement.",new[]{"Linear · direct response, no software smoothing. Example: a small tilt produces a proportional movement.","Линейный — прямой отклик без программного сглаживания: малый наклон даёт пропорциональное движение."});
   entries.Add("Adaptive · steadies slow motion and follows quick changes more closely. Example: less reticle jitter while aiming, faster response for a turn.",new[]{"Adaptive · steadies slow motion and follows quick changes more closely. Example: less reticle jitter while aiming, faster response for a turn.","Адаптивный — стабилизирует медленное движение, быстрее следует за резким. Меньше дрожания при наведении, быстрый отклик при повороте."});
   entries.Add("Precision · slower output for small movements, faster output for large turns, plus adaptive smoothing. Example: line up a distant target, then turn quickly.",new[]{"Precision · slower output for small movements, faster output for large turns, plus adaptive smoothing. Example: line up a distant target, then turn quickly.","Точный — замедляет малые движения, ускоряет большие и добавляет адаптивное сглаживание. Удобно для дальнего прицеливания и быстрых разворотов."});
   entries.Add("Small movements",new[]{"Small movements","Малые движения"});
   entries.Add("Gyro gate ignores tiny rotations before filtering. Example: 1.0°/s stops output below that speed, including the smoothing tail. 0 is Off; each step is 0.1°/s.",new[]{"Gyro gate ignores tiny rotations before filtering. Example: 1.0°/s stops output below that speed, including the smoothing tail. 0 is Off; each step is 0.1°/s.","Порог гироскопа убирает мелкие вращения до фильтрации. 1,0°/s обнуляет выход ниже этой скорости, включая затухание сглаживания. 0 — выкл.; шаг 0,1°/s."});
   entries.Add("Anti-deadzone is for stick targets only. Example: 20% raises a tiny gyro movement to a 20% stick radius so it can pass the game's deadzone. A zero sensor reading creates no output. If idle noise moves the reticle, add a small Gyro gate. Use 0 if your game needs no compensation.",new[]{"Anti-deadzone is for stick targets only. Example: 20% raises a tiny gyro movement to a 20% stick radius so it can pass the game's deadzone. A zero sensor reading creates no output. If idle noise moves the reticle, add a small Gyro gate. Use 0 if your game needs no compensation.","Антимёртвая зона действует только для стиков: 20% поднимает малое движение до радиуса 20%, преодолевая мёртвую зону игры. Нулевой датчик не даёт выхода. При дрейфе добавьте небольшой порог. Если компенсация не нужна, выберите 0."});
   entries.Add("Controller firmware",new[]{"Controller firmware","Прошивка контроллера"});
   entries.Add("Read current hardware assignments and stick / trigger settings. Existing assignments are preserved.",new[]{"Read current hardware assignments and stick / trigger settings. Existing assignments are preserved.","Прочитать аппаратные назначения и настройки стиков / триггеров. Назначения сохраняются."});
   entries.Add("Read firmware settings",new[]{"Read firmware settings","Прочитать настройки прошивки"});
   entries.Add("Hardware layers: {0} / {1} assignments\nM1: {2} · M2: {3}\nHome: {4} · G-Key: {5}\nStick / trigger settings read. Firmware assignments are unchanged.",new[]{"Hardware layers: {0} / {1} assignments\nM1: {2} · M2: {3}\nHome: {4} · G-Key: {5}\nStick / trigger settings read. Firmware assignments are unchanged.","Аппаратные слои: {0} / {1} назначений\nM1: {2} · M2: {3}\nHome: {4} · G-Key: {5}\nНастройки стиков и триггеров считаны. Назначения прошивки не менялись."});
   entries.Add("Input check unavailable. Try Refresh status again.",new[]{"Input check unavailable. Try Refresh status again.","Проверка ввода недоступна. Повторите обновление состояния."});
   entries.Add("Input check unavailable: {0}",new[]{"Input check unavailable: {0}","Проверка ввода недоступна: {0}"});
   entries.Add("Input check requires an updated ONEXTweaks helper.",new[]{"Input check requires an updated ONEXTweaks helper.","Для проверки ввода нужен обновлённый помощник ONEXTweaks."});
   entries.Add("Input visibility · Not checked\nRefresh status checks what games can see. It does not change drivers or input settings.",new[]{"Input visibility · Not checked\nRefresh status checks what games can see. It does not change drivers or input settings.","Видимость ввода · Не проверена\nОбновление проверяет устройства, видимые играм. Драйверы и настройки ввода не меняются."});
   entries.Add("Nintendo Switch layout",new[]{"Nintendo Switch layout","Раскладка Nintendo Switch"});
   entries.Add("Меняет A ↔ B и X ↔ Y в конечном виртуальном выходе — после назначений кнопок и макросов. Сохраняется в текущий профиль. Нужны Virtual Controller и Full Remapping On. Навигация самого виджета остаётся обычной Xbox; клавомышь не меняется.",new[]{"Swaps A ↔ B and X ↔ Y in the final virtual output, after mappings and macros. Saved in this profile. Requires Virtual Controller and Full Remapping On. Widget navigation stays in Xbox layout; Keyboard & mouse is unchanged.","Меняет A ↔ B и X ↔ Y на конечном виртуальном выходе после назначений и макросов. Сохраняется в профиле. Нужны виртуальный контроллер и полное переназначение. Навигация виджета остаётся в раскладке Xbox; клавиатура и мышь не меняются."});
   entries.Add("Sequence · choose a step",new[]{"Sequence · choose a step","Последовательность · выберите шаг"});
   entries.Add("Gamepad button for this step",new[]{"Gamepad button for this step","Кнопка геймпада для этого шага"});
   entries.Add("Gyro calibration",new[]{"Gyro calibration","Калибровка гироскопа"});
   entries.Add("Check the motion sensors or calibrate idle drift",new[]{"Check the motion sensors or calibrate idle drift","Проверка датчиков и калибровка дрейфа в покое"});
   entries.Add("Last angular rate: —",new[]{"Last angular rate: —","Угловая скорость: —"});
   entries.Add("Idle correction: not calibrated",new[]{"Idle correction: not calibrated","Коррекция покоя: нет калибровки"});
   entries.Add("Lay the console on a steady surface, then choose Calibrate gyro. Keep it still for 3 seconds. Calibration removes idle drift: for example, a stationary 0.2°/s becomes 0°/s. The correction is shared by all controller profiles.",new[]{"Lay the console on a steady surface, then choose Calibrate gyro. Keep it still for 3 seconds. Calibration removes idle drift: for example, a stationary 0.2°/s becomes 0°/s. The correction is shared by all controller profiles.","Положите консоль на устойчивую поверхность и нажмите «Калибровать гироскоп». Не двигайте её 3 секунды. Калибровка убирает дрейф: неподвижные 0,2°/s станут 0°/s. Коррекция общая для всех профилей."});
   entries.Add("Last angular rate: {0}",new[]{"Last angular rate: {0}","Угловая скорость: {0}"});
   entries.Add("not calibrated",new[]{"not calibrated","нет калибровки"});
   entries.Add("Idle correction: {0}",new[]{"Idle correction: {0}","Коррекция покоя: {0}"});
   entries.Add("Measuring · keep still",new[]{"Measuring · keep still","Измерение · не двигайте консоль"});
   entries.Add("Calibrated · idle drift",new[]{"Calibrated · idle drift","Калибровано · дрейф покоя"});
   entries.Add("Windows sensor · not calibrated",new[]{"Windows sensor · not calibrated","Датчик Windows · не калиброван"});
   entries.Add("Sensor check & calibration",new[]{"Sensor check & calibration","Проверка и калибровка датчиков"});
   entries.Add("Settings stored in this profile",new[]{"Settings stored in this profile","Группы настроек этого профиля"});
   entries.Add("Checked: use this profile’s settings. Unchecked: follow Global Profile; editing that setting updates Global. Separate values are kept for when you check it again.",new[]{"Checked: use this profile’s settings. Unchecked: follow Global Profile; editing that setting updates Global. Separate values are kept for when you check it again.","Включено — использовать настройки этого профиля. Выключено — наследовать глобальный; редактирование меняет глобальные значения. Собственные значения сохраняются для повторного включения."});
   entries.Add("Controller type, stick/trigger tuning and gyro settings always stay in this profile. Game lighting requires Virtual Controller + DualShock 4.",new[]{"Controller type, stick/trigger tuning and gyro settings always stay in this profile. Game lighting requires Virtual Controller + DualShock 4.","Тип контроллера, стики, триггеры и гироскоп всегда хранятся в этом профиле. Цвета игры требуют виртуального DualShock 4."});
   entries.Add("Use Hardware Controller for this Profile",new[]{"Use Hardware Controller for this Profile","Аппаратный контроллер для этого профиля"});
   entries.Add("Игра получит штатный геймпад напрямую. Переназначения, режим мыши и настройки стиков виртуального контроллера для этого профиля применяться не будут. Например, включи это для игры, которая не принимает виртуальный Xbox-контроллер. Кнопка ONEXTweaks продолжит работать. При выборе другого профиля вернётся общий режим Controller Mode.",new[]{"The game receives the native gamepad directly. This profile's virtual remaps, mouse mode and stick settings do not apply. Use it for games that reject a virtual Xbox controller. The ONEXTweaks button still works. Selecting another profile restores the general Controller Mode.","Игра получает штатный геймпад напрямую, без виртуальных назначений, мыши и настроек стиков этого профиля. Подходит играм, не принимающим виртуальный Xbox. Кнопка ONEXTweaks работает. Другой профиль возвращает общий режим контроллера."});
   entries.Add("Сохранится для этого профиля и применится, когда он станет активным.",new[]{"Saved for this profile; applies when it becomes active.","Сохраняется для этого профиля и применяется при его активации."});
   entries.Add("Общий Controller Mode сейчас Hardware. Исключение сохранится для следующего включения Virtual Controller.",new[]{"The general Controller Mode is Hardware. This exception is saved for the next time Virtual Controller is enabled.","Общий режим сейчас аппаратный. Исключение сохранено для следующего включения виртуального контроллера."});
   entries.Add("Для этого профиля используется штатный геймпад. Общий Virtual Controller включится при выходе из профиля.",new[]{"This profile uses the native gamepad. Leaving it restores the general Virtual Controller mode.","Профиль использует штатный геймпад. Выход из него возвращает общий виртуальный режим."});
   entries.Add("Используется общий Controller Mode. Привязанный игровой профиль выбирается автоматически при запуске игры.",new[]{"Uses the general Controller Mode. A linked game profile is selected automatically when the game starts.","Используется общий режим контроллера. Связанный игровой профиль выбирается при запуске игры."});
   entries.Add("Rumble profile",new[]{"Rumble profile","Профиль вибрации"});
   entries.Add("Balanced — обычный отклик. Sharp усиливает мелкую вибрацию и ослабляет тяжёлую; Soft делает обе мягче; Impact усиливает тяжёлую; Boosted усиливает обе. Это наши ограниченные уровнем мощности варианты обработки, а не аппаратные пресеты прошивки.",new[]{"Balanced is the normal response. Sharp emphasizes light rumble and reduces heavy rumble; Soft softens both; Impact strengthens heavy rumble; Boosted strengthens both. These are our power-limited software responses, not firmware hardware presets.","Сбалансированный — обычный отклик. Резкий усиливает мелкую вибрацию и ослабляет тяжёлую; Мягкий смягчает обе; Ударный усиливает тяжёлую; Усиленный — обе. Это ограниченные по мощности программные варианты, а не пресеты прошивки."});
  }
  static void Add21(Dictionary<string,string[]> entries)
  {
   entries.Add("Меняет каналы тяжёлой и мелкой вибрации местами после выбранного пресета. Интенсивность остаётся общим пределом; 0% всегда выключает оба мотора.",new[]{"Swaps heavy and light rumble channels after the selected preset. Intensity remains the overall limit; 0% always turns both motors off.","Меняет тяжёлый и лёгкий каналы после выбранного пресета. Сила остаётся общим пределом; 0% отключает оба мотора."});
   entries.Add("Virtual Controller: all supported gamepad, macro, keyboard, mouse and system actions are available. Changes are saved in the selected profile.",new[]{"Virtual Controller: all supported gamepad, macro, keyboard, mouse and system actions are available. Changes are saved in the selected profile.","Виртуальный контроллер: доступны поддерживаемые действия геймпада, макросы, клавиатура, мышь и системные команды. Изменения сохраняются в выбранном профиле."});
   entries.Add("Hardware Controller: only Open ONEXTweaks, Windows keyboard and Steam actions are available. Gamepad, macro, keyboard and mouse remaps require Virtual Controller. Saved virtual-only assignments are kept.",new[]{"Hardware Controller: only Open ONEXTweaks, Windows keyboard and Steam actions are available. Gamepad, macro, keyboard and mouse remaps require Virtual Controller. Saved virtual-only assignments are kept.","Аппаратный контроллер: доступны открытие ONEXTweaks, клавиатура Windows и действия Steam. Назначения геймпада, макросов, клавиш и мыши требуют виртуального режима. Сохранённые назначения остаются в профиле."});
   entries.Add("Checking VIIPER installation…",new[]{"Checking VIIPER installation…","Проверка установки VIIPER…"});
