   entries.Add("0 — Off. Уровни 1–{0} усиливают контуры: например, 1 — лёгкая резкость, максимальный — сильная.",new[]{"0 — Off. Levels 1–{0} sharpen edges: 1 is subtle and the maximum is strong.","0 — выкл. Уровни 1–{0} усиливают контуры: 1 — слегка, максимальный — сильно."});
   entries.Add("Сначала выбери разрешение ниже 1920×1200 в Resolution & Refresh Rate.",new[]{"First choose a resolution below 1920×1200 in Resolution & Refresh Rate.","Сначала выберите разрешение ниже 1920×1200 в блоке разрешения и частоты."});
   entries.Add("GPU — обычное; Retro — чёткие пиксели.",new[]{"GPU is normal scaling; Retro keeps crisp pixels.","GPU — обычное масштабирование; Retro — чёткие пиксели."});
   entries.Add("При родном разрешении масштабирование не требуется.",new[]{"Scaling is not needed at the native resolution.","При родном разрешении масштабирование не требуется."});
