   entries.Add("Integer: увеличение только в целое число раз, без размытия пикселей. Если целый масштаб не заполняет экран, остаются поля.",new[]{"Integer enlarges by whole-number factors without blurring pixels. Unfilled space remains as borders.","Целочисленный масштаб увеличивает без размытия пикселей. Если изображение не заполняет экран, остаются поля."});
   entries.Add("Nearest Neighbour: заполняет экран без сглаживания пикселей; при дробном масштабе они могут иметь разную ширину.",new[]{"Nearest Neighbour fills the screen without smoothing pixels; fractional scaling may produce uneven pixel widths.","Ближайший сосед заполняет экран без сглаживания; при дробном масштабе пиксели могут отличаться по ширине."});
