   entries.Add("Mouse acceleration",new[]{"Mouse acceleration","Ускорение мыши"});
   entries.Add("Adaptive scroll",new[]{"Adaptive scroll","Адаптивная прокрутка"});
   entries.Add("Точнее у центра стика, быстрее у края. Off — линейная скорость.",new[]{"More precise near the stick centre, faster at the edge. Off uses linear speed.","Точнее около центра стика, быстрее у края. Выкл. — линейная скорость."});
   entries.Add("Чем сильнее отклонён стик, тем быстрее прокрутка. Off — постоянная скорость.",new[]{"Stronger stick deflection scrolls faster. Off uses constant speed.","Сильнее отклонён стик — быстрее прокрутка. Выкл. — постоянная скорость."});
   entries.Add("FN modifier · hold",new[]{"FN modifier · hold","Модификатор FN · удержание"});
   entries.Add("FN — одна из Home, G-Key, M1 или M2. Keyboard и ONEX передают системные сочетания; удержание для FN на них не подтверждено. Удерживай FN для второго слоя; без FN используются основные назначения. Двойной Keyboard всегда переключает режим.",new[]{"FN can be Home, G-Key, M1 or M2. Keyboard and ONEX send system shortcuts; FN holding is not confirmed for them. Hold FN for the second layer; otherwise use base assignments. Double Keyboard always switches mode.","FN можно назначить на Home, G-Key, M1 или M2. Keyboard и ONEX передают системные сочетания; удержание FN на них не подтверждено. Удерживайте FN для второго слоя. Двойной Keyboard всегда переключает режим."});
