  static void Add25(Dictionary<string,string[]> entries)
  {
   entries.Add("Reset to Windows · Boost Off",new[]{"Reset to Windows · Boost Off","Сбросить к Windows · Boost выкл."});
   entries.Add("Windows CPU State",new[]{"Windows CPU State","Состояние CPU в Windows"});
   entries.Add("FPS",new[]{"FPS","FPS"});
   entries.Add("Intel использует лимитер драйвера; RTSS — свой лимитер. Например, 60 FPS ограничивает скорость кадров, если выбранный способ поддерживает эту игру.",new[]{"Intel uses its driver limiter; RTSS uses its own limiter. For example, 60 FPS caps frame rate when the chosen method supports that game.","Intel использует ограничитель драйвера, RTSS — свой. Например, 60 FPS ограничивает частоту кадров, если способ поддерживает эту игру."});
   entries.Add("Frame Gen может требовать перезапуска игры. VRR зависит от поддержки дисплея и разрешения; масштабирование заметно при разрешении ниже родного. Эти настройки не выбирают и не изменяют Screen Color Profile.",new[]{"Frame Gen may require restarting the game. VRR depends on display support and resolution; scaling matters below native resolution. These settings do not select or change Screen Color Profiles.","Генерация кадров может требовать перезапуска игры. VRR зависит от дисплея и разрешения; масштабирование заметно ниже родного разрешения. Эти параметры не меняют профили цветов экрана."});
   entries.Add("Здесь выбирается профиль. Его настройки находятся на вкладке Fan.",new[]{"Choose the profile here. Its settings are on the Fan tab.","Здесь выбирается профиль. Настройки находятся на вкладке вентилятора."});
