   entries.Add("Off · direct motion for DS4 games. Enable to see setup details.",new[]{"Off · direct motion for DS4 games. Enable to see setup details.","Выкл. · передача движения в игры DS4. Включите, чтобы увидеть подробности."});
   entries.Add("Place the console on a steady surface for three seconds. Calibration removes idle rotation bias, not gravity. Accelerometer values can stay nonzero when tilted. The correction is shared by profiles.",new[]{"Place the console on a steady surface for three seconds. Calibration removes idle rotation bias, not gravity. Accelerometer values can stay nonzero when tilted. The correction is shared by profiles.","Положите консоль на устойчивую поверхность на три секунды. Калибровка убирает дрейф вращения в покое, а не гравитацию. При наклоне акселерометр может показывать ненулевые значения. Коррекция общая для всех профилей."});
   entries.Add("Gyro & motion · live test",new[]{"Gyro & motion · live test","Гироскоп и движение · тест"});
   entries.Add("Console movement",new[]{"Console movement","Движение консоли"});
   entries.Add("Recenter view",new[]{"Recenter view","Центрировать схему"});
   entries.Add("Relative orientation",new[]{"Relative orientation","Относительная ориентация"});
   entries.Add("Relative rotation · X / Y / Z",new[]{"Relative rotation · X / Y / Z","Относительный поворот · X / Y / Z"});
   entries.Add("Yaw · Y",new[]{"Yaw · Y","Рыскание · Y"});
