   entries.Add("ONEXPLAYER 3 motion model",new[]{"ONEXPLAYER 3 motion model","Модель движения ONEXPLAYER 3"});
   entries.Add("The 3D model could not load.",new[]{"The 3D model could not load.","Не удалось загрузить 3D-модель."});
   entries.Add("The 3D model follows the calibrated rotation of the console. Gravity stabilizes tilt. Relative rotation shows the angle components along X, Y and Z. Rotation about gravity can drift. Recenter sets a new reference for the view.",new[]{"The 3D model follows the calibrated rotation of the console. Gravity stabilizes tilt. Relative rotation shows the angle components along X, Y and Z. Rotation about gravity can drift. Recenter sets a new reference for the view.","3D-модель следует за вращением консоли с учётом калибровки. Данные о гравитации стабилизируют наклон. Относительный поворот показывает компоненты угла по осям X, Y и Z. При вращении вокруг вертикали возможен дрейф. Центрирование задаёт новую точку отсчёта для модели."});
   entries.Add("The accepted console drawing follows calibrated body rotation, with gravity helping stabilize tilt. This is orientation relative to the start, not an absolute compass heading. Yaw can drift. Recenter changes only this display; it does not recalibrate the sensors.",new[]{"The accepted console drawing follows calibrated body rotation, with gravity helping stabilize tilt. This is orientation relative to the start, not an absolute compass heading. Yaw can drift. Recenter changes only this display; it does not recalibrate the sensors.","Схема консоли следует за вращением с учётом калибровки. Гравитация помогает стабилизировать наклон. Это положение относительно начала теста, а не показания компаса; курс может дрейфовать. Центрирование меняет только схему и не затрагивает калибровку сенсоров."});
   entries.Add("Angular speed · Raw / calibrated",new[]{"Angular speed · Raw / calibrated","Скорость вращения · исходная / калиброванная"});
   entries.Add("The dials show angular speed in °/s on the gyroscope’s own axes. White shows the raw value. Colour shows the value after idle calibration. The dials span ±180°/s and the numbers show the full reading.",new[]{"The dials show angular speed in °/s on the gyroscope’s own axes. White shows the raw value. Colour shows the value after idle calibration. The dials span ±180°/s and the numbers show the full reading.","Диаграммы показывают скорость вращения в °/с по осям самого гироскопа. Белая стрелка показывает исходное значение, цветная — значение после калибровки в покое. Шкала охватывает ±180°/с, числа показывают полное значение."});
   entries.Add("Pitch · X",new[]{"Pitch · X","Тангаж · X"});
   entries.Add("Yaw · −Y",new[]{"Yaw · −Y","Рыскание · −Y"});
   entries.Add("Roll · −Z",new[]{"Roll · −Z","Крен · −Z"});
   entries.Add("Processed aiming preview",new[]{"Processed aiming preview","Предпросмотр обработки прицеливания"});
   entries.Add("This independent test uses the selected profile and the same processing code as gameplay, but sends no test output to games. Hold/Toggle/Boost follow your physical buttons. Off or inactive activation gives no output. Mouse counts are per measured tick, not an angle. Aiming settings do not rotate the console drawing.",new[]{"This independent test uses the selected profile and the same processing code as gameplay, but sends no test output to games. Hold/Toggle/Boost follow your physical buttons. Off or inactive activation gives no output. Mouse counts are per measured tick, not an angle. Aiming settings do not rotate the console drawing.","Тест использует выбранный профиль и тот же код обработки, что в игре, но не отправляет тестовый ввод. Hold, Toggle и Boost реагируют на физические кнопки. При выключенном или неактивном прицеливании выхода нет. Смещения мыши даны за измеренный такт, а не в градусах. Настройки прицеливания не поворачивают схему консоли."});
   entries.Add("Resolved °/s",new[]{"Resolved °/s","После выбора осей, °/с"});
   entries.Add("Filtered °/s",new[]{"Filtered °/s","После фильтра, °/с"});
   entries.Add("Target contribution",new[]{"Target contribution","Выход прицеливания"});
   entries.Add("Calibration",new[]{"Calibration","Калибровка"});
   entries.Add("Subtracts the saved idle angular bias on each sensor axis. Acceleration still includes gravity.",new[]{"Subtracts the saved idle angular bias on each sensor axis. Acceleration still includes gravity.","Вычитает сохранённый дрейф покоя из скорости вращения по каждой оси. Ускорение по-прежнему включает гравитацию."});
   entries.Add("Axes",new[]{"Axes","Оси"});
   entries.Add("Gravity-relative or local yaw/roll selection resolves two aiming channels. Rotation and inversion transform those output channels.",new[]{"Gravity-relative or local yaw/roll selection resolves two aiming channels. Rotation and inversion transform those output channels.","По гравитации или выбранным локальным осям формируются два канала прицеливания. Поворот и инверсия преобразуют эти выходные каналы."});
   entries.Add("Gate / curve",new[]{"Gate / curve","Порог / кривая"});
   entries.Add("Gate rejects small 2D rates and clears the filter tail. A custom curve can reject input below its own deadzone and shapes stick output. Anti-deadzone applies only to nonzero standard stick output.",new[]{"Gate rejects small 2D rates and clears the filter tail. A custom curve can reject input below its own deadzone and shapes stick output. Anti-deadzone applies only to nonzero standard stick output.","Порог отсекает малые скорости по двум осям и сбрасывает остаток фильтра. Своя кривая может отсекать ввод внутри собственной мёртвой зоны и задаёт отклик стика. Антимёртвая зона действует только на ненулевой стандартный выход стика."});
   entries.Add("Filter / gain",new[]{"Filter / gain","Фильтр / усиление"});
   entries.Add("Linear is direct; Adaptive smooths changing rates; Precision also uses speed-based gain. Sensitivity and a held Boost button scale the output. The table shows the actual stages reached, not invented values for inactive stages.",new[]{"Linear is direct; Adaptive smooths changing rates; Precision also uses speed-based gain. Sensitivity and a held Boost button scale the output. The table shows the actual stages reached, not invented values for inactive stages.","Linear передаёт напрямую, Adaptive сглаживает меняющуюся скорость, Precision дополнительно меняет усиление по скорости. Чувствительность и удержание Boost масштабируют выход. Показаны реально достигнутые этапы обработки; неактивные этапы не подменяются нулями."});
   entries.Add("Accelerometer · g",new[]{"Accelerometer · g","Акселерометр · g"});
   entries.Add("Acceleration includes gravity. When held at an angle, nonzero X/Y/Z is normal. The magnitude is usually around 1g at rest; dynamic movement adds acceleration. Gyro calibration does not remove gravity.",new[]{"Acceleration includes gravity. When held at an angle, nonzero X/Y/Z is normal. The magnitude is usually around 1g at rest; dynamic movement adds acceleration. Gyro calibration does not remove gravity.","Ускорение включает гравитацию. При неподвижном наклоне ненулевые X/Y/Z нормальны. В покое модуль обычно около 1g, движение добавляет ускорение. Калибровка гироскопа не убирает гравитацию."});
   entries.Add("Magnitude",new[]{"Magnitude","Модуль"});
   entries.Add("Raw sensor and profile preview · no settings are changed",new[]{"Raw sensor and profile preview · no settings are changed","Сенсоры и предпросмотр профиля · настройки не меняются"});
