   entries.Add("Choose an engine. Adaptive and Precision reveal Smoothing; Linear uses direct input.",new[]{"Choose an engine. Adaptive and Precision reveal Smoothing; Linear uses direct input.","Выберите движок. Adaptive и Precision позволяют настроить сглаживание; Linear передаёт напрямую."});
   entries.Add("SensorUnavailable",new[]{"Motion data unavailable","Данные движения недоступны"});
